// Freehand coordinates are normalized to the original floor overview, independent of zoom.
// Además del lápiz, cada piso guarda recintos marcados completos (rooms: {código: color}) y el avance calculado por
// superficie (avance), para mostrarlo en el formulario sin recalcular (payment-plan-rooms.mjs).
import {cargarRecintos,recintoEn,medirAvance,resumirAvance,avanceGuardado,COLORES,NOMBRES} from './payment-plan-rooms.mjs';
const floors={'N-1':'',N01:'n01/',N02:'n02/',N03:'n03/'},colors=Object.keys(COLORES),names={'N-1':'Piso −1',N01:'Piso 1',N02:'Piso 2',N03:'Piso 3'};
export function latestPaymentPlan(rows,contractor){return structuredClone(rows.filter(r=>r.contractor===contractor&&r.plan).sort((a,b)=>String(b.period).localeCompare(String(a.period))||String(b.at).localeCompare(String(a.at)))[0]?.plan||{schema:1,floors:{}});}
export function validatePlan(plan){if(plan==null)return;if(plan.schema!==1||!plan.floors||JSON.stringify(plan).length>40000)throw Error('Plano demasiado grande o incompatible.');for(const [floor,sheet]of Object.entries(plan.floors)){if(!(floor in floors)||!Array.isArray(sheet.strokes)||sheet.strokes.length>300)throw Error('Plano inválido');for(const stroke of sheet.strokes){if(!colors.includes(stroke.color)||!Array.isArray(stroke.points)||stroke.points.length<1||stroke.points.some(p=>!Array.isArray(p)||p.length!==2||p.some(n=>!Number.isFinite(n)||n<0||n>1))||(stroke.w!=null&&!(Number.isFinite(stroke.w)&&stroke.w>0&&stroke.w<=.05)))throw Error('Trazo inválido');}
 if(sheet.rooms!=null){if(typeof sheet.rooms!=='object'||Array.isArray(sheet.rooms)||Object.keys(sheet.rooms).length>800)throw Error('Recintos marcados inválidos');for(const [code,color]of Object.entries(sheet.rooms))if(!/^[\w.\-' ]{1,60}$/.test(code)||!colors.includes(color))throw Error('Recinto marcado inválido');}
 if(sheet.avance!=null&&(typeof sheet.avance!=='object'||Array.isArray(sheet.avance)||Object.values(sheet.avance).some(v=>!Number.isFinite(v)||v<0)))throw Error('Avance inválido');}}
// Recintos con contorno por piso, cargados una vez por sesión del diálogo.
const roomCache=new Map(),roomsOf=floor=>{if(!roomCache.has(floor))roomCache.set(floor,cargarRecintos(floors[floor]).catch(e=>{roomCache.delete(floor);throw e;}));return roomCache.get(floor);};
const fmt=(v,d=0)=>v.toLocaleString('es-CL',{maximumFractionDigits:d,minimumFractionDigits:d}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function openPaymentPlan(plan,onSave,{readOnly=false}={}){
 const draft=structuredClone(plan||{schema:1,floors:{}}),dialog=document.createElement('dialog');dialog.className='paymentPlan';dialog.innerHTML='<h2>Avance dibujado del pago</h2><div class="planAvance" aria-live="polite"></div><p>Verde: ejecutado · Naranja: pendiente · Rojo: observación. <b>Recinto</b> marca el recinto completo (tócalo de nuevo con el mismo estado para quitarlo); <b>Lápiz</b> pinta solo una parte. El avance se calcula por superficie de los recintos marcados o pintados.</p><div class="planTools"><select aria-label="Piso del dibujo"><option value="N-1">Piso −1</option><option value="N01">Piso 1</option><option value="N02">Piso 2</option><option value="N03">Piso 3</option></select><button type="button" data-mode="room">Recinto</button><button type="button" data-mode="draw">Lápiz</button><button type="button" data-mode="pan">Mover</button><select aria-label="Estado"><option value="#21854b">Ejecutado</option><option value="#d68b20">Pendiente</option><option value="#c83c3c">Observación</option></select><select aria-label="Grosor del lápiz"><option value="0.003">Línea fina</option><option value="0.012">Pincel medio</option><option value="0.03">Pincel grueso</option></select><button type="button" data-zoom="0.7">+</button><button type="button" data-zoom="1.4">−</button><button type="button" id="undoPlan">Deshacer</button></div><p class="planStatus" role="status"></p><svg class="paymentPlanSvg" xmlns="http://www.w3.org/2000/svg"><image/><g class="planRooms"/><g/></svg><button type="button" id="applyPlan">Conservar dibujo en este formulario</button><button type="button" id="cancelPlan">Cancelar</button><p>Para guardarlo en la nube, pulsa Guardar en el estado de pago.</p>';
 document.body.append(dialog);if(readOnly){dialog.querySelector('h2').textContent='Plano guardado · solo lectura';dialog.querySelector('#applyPlan').hidden=true;dialog.querySelector('#undoPlan').hidden=true;dialog.querySelector('[data-mode=draw]').hidden=true;dialog.querySelector('[data-mode=room]').hidden=true;dialog.querySelectorAll('select')[1].hidden=true;dialog.querySelectorAll('select')[2].hidden=true;dialog.querySelector('#cancelPlan').textContent='Cerrar';dialog.querySelector('p:last-child').textContent='Copia del dibujo guardado en esta versión del pago.';}dialog.showModal();const svg=dialog.querySelector('svg'),image=svg.querySelector('image'),roomLayer=svg.querySelector('.planRooms'),group=svg.querySelector('g:not(.planRooms)'),selectors=dialog.querySelectorAll('select'),status=dialog.querySelector('.planStatus'),summary=dialog.querySelector('.planAvance');let floor='N-1',mode=readOnly?'pan':'room',width=1000,height=1000,view=[0,0,1000,1000],active=null,serial=0,rooms=[],history=[],timer=0;
 dialog.querySelectorAll('[data-mode]').forEach(btn=>btn.setAttribute('aria-pressed',String(btn.dataset.mode===mode)));
 const updateView=()=>svg.setAttribute('viewBox',view.join(' '));
 const ringPath=r=>r.anillos.map(a=>[a.polygon,...a.holes].map(ring=>'M'+ring.map(p=>(p[0]*width)+' '+(p[1]*height)).join('L')+'Z').join('')).join('');
 // Recintos marcados (relleno) y, en modo Recinto, los contornos tocables; encima, los trazos con su grosor.
 const render=()=>{const sheet=draft.floors[floor],marked=sheet?.rooms||{};roomLayer.innerHTML=rooms.map(r=>{const color=marked[r.codigo];return color?`<path d="${ringPath(r)}" fill="${color}" fill-opacity=".38" stroke="${color}" stroke-width="${width*.0012}" fill-rule="evenodd"/>`:mode==='room'?`<path d="${ringPath(r)}" fill="none" stroke="#386c84" stroke-opacity=".35" stroke-width="${width*.0008}"/>`:'';}).join('');group.innerHTML='';for(const stroke of sheet?.strokes||[]){const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',stroke.points.map((p,i)=>(i?'L':'M')+(p[0]*width)+' '+(p[1]*height)).join(' ')+(stroke.points.length===1?' l0.01 0':''));path.setAttribute('fill','none');path.setAttribute('stroke',stroke.color);path.setAttribute('stroke-width',String(width*(stroke.w||.003)));path.setAttribute('stroke-opacity',(stroke.w||.003)>.003?'.6':'1');path.setAttribute('stroke-linecap','round');path.setAttribute('stroke-linejoin','round');group.append(path);}};
 // Porcentajes por superficie del piso actual; se guardan en el plano para verlos en el formulario.
 const showSummary=r=>{const parts=['ejecutado','pendiente','observacion','sinMarcar'];summary.innerHTML=!r.recintos?`<b>${names[floor]}</b> · aún no hay recintos marcados ni pintados.`:`<div class="planAvanceHead"><b>${names[floor]}</b> · ${r.recintos} recintos · ${fmt(r.m2,1)} m²</div><div class="planBar">${parts.map(k=>`<i class="${k}" style="width:${r.partes[k].pct}%"></i>`).join('')}</div><div class="planCifras">${parts.map(k=>`<span class="${k}"><b>${fmt(r.partes[k].pct,1)} %</b> ${NOMBRES[k]} · ${fmt(r.partes[k].m2,1)} m²</span>`).join('')}</div><details><summary>Detalle por recinto</summary><table><thead><tr><th>Recinto</th><th>m²</th><th>Ejec.</th><th>Pend.</th><th>Obs.</th></tr></thead><tbody>${r.detalle.map(d=>`<tr><td><b>${esc(d.codigo)}</b> ${esc(d.nombre)}${d.marcado?'':' <small>(lápiz)</small>'}</td><td>${fmt(d.m2,1)}</td><td>${fmt(d.ejecutado)} %</td><td>${fmt(d.pendiente)} %</td><td>${fmt(d.observacion)} %</td></tr>`).join('')}</tbody></table></details>`;};
 const measure=()=>{clearTimeout(timer);timer=setTimeout(()=>{if(!rooms.length||!dialog.isConnected)return;const sheet=draft.floors[floor];const result=resumirAvance(medirAvance(rooms,sheet,height/width));showSummary(result);if(sheet&&!readOnly)sheet.avance=avanceGuardado(result);},120);};
 async function load(){const request=++serial;active=null;rooms=[];status.textContent='Cargando plano…';summary.textContent='';svg.style.pointerEvents='none';const url=floors[floor]+'map/overview.webp',img=new Image();img.src=url;try{await img.decode();if(request!==serial||!dialog.isConnected)return;width=img.naturalWidth;height=img.naturalHeight;image.setAttribute('href',url);image.setAttribute('width',width);image.setAttribute('height',height);view=[0,0,width,height];updateView();draft.floors[floor]??={source:url,strokes:[]};render();svg.style.pointerEvents='auto';status.textContent='Cargando recintos…';}catch{status.textContent='No se pudo cargar el plano de este piso.';return;}
  try{const loaded=await roomsOf(floor);if(request!==serial||!dialog.isConnected)return;rooms=loaded;render();measure();status.textContent=readOnly?'Mover desplaza el plano; usa + para acercar.':'Recinto marca el recinto completo; Lápiz pinta una parte; Mover desplaza el plano. Usa + para acercar.';}catch{status.textContent='No se pudieron cargar los recintos de este piso: el lápiz funciona, pero no se calcula el avance.';}}
 selectors[0].onchange=()=>{floor=selectors[0].value;load();};dialog.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;dialog.querySelectorAll('[data-mode]').forEach(btn=>btn.setAttribute('aria-pressed',String(btn===b)));render();});dialog.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{const k=Number(b.dataset.zoom);if(view[2]*k<width/30||view[2]*k>width*2)return;view=[view[0]+view[2]*(1-k)/2,view[1]+view[3]*(1-k)/2,view[2]*k,view[3]*k];updateView();});
 const point=e=>new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());
 // Tocar un recinto lo marca con el estado elegido; tocarlo de nuevo con el mismo estado lo desmarca.
 const toggleRoom=p=>{const r=recintoEn(rooms,[p.x/width,p.y/height]);if(!r){status.textContent='Ahí no hay un recinto con contorno.';return;}const sheet=draft.floors[floor],marked=sheet.rooms??={},before=marked[r.codigo]??null,color=selectors[1].value;if(before===color)delete marked[r.codigo];else marked[r.codigo]=color;history.push({floor,room:r.codigo,before});status.textContent=`${r.codigo} · ${r.nombre}: ${before===color?'desmarcado':NOMBRES[COLORES[color]].toLowerCase()}.`;render();measure();};
 svg.onpointerdown=e=>{if(active)return;e.preventDefault();const p=point(e);if(mode==='room'){toggleRoom(p);return;}svg.setPointerCapture(e.pointerId);if(mode==='draw'){const w=Number(selectors[2].value),stroke={color:selectors[1].value,points:[[Math.max(0,Math.min(1,p.x/width)),Math.max(0,Math.min(1,p.y/height))]],...(w!==.003?{w}:{})};draft.floors[floor].strokes.push(stroke);history.push({floor,stroke:true});active={id:e.pointerId,stroke};render();}else active={id:e.pointerId,x:e.clientX,y:e.clientY,view:[...view],scale:svg.getScreenCTM().a};};svg.onpointermove=e=>{if(active?.id!==e.pointerId)return;e.preventDefault();if(active.stroke){const p=point(e);active.stroke.points.push([Math.round(Math.max(0,Math.min(1,p.x/width))*10000)/10000,Math.round(Math.max(0,Math.min(1,p.y/height))*10000)/10000]);render();}else{view=[active.view[0]-(e.clientX-active.x)/active.scale,active.view[1]-(e.clientY-active.y)/active.scale,active.view[2],active.view[3]];updateView();}};svg.onpointerup=e=>{if(active?.id===e.pointerId){if(active.stroke)measure();active=null;}};svg.onpointercancel=e=>{if(active?.id===e.pointerId){if(active.stroke){draft.floors[floor].strokes.pop();history.pop();}active=null;render();}};
 // Deshacer: el último trazo o la última marca de recinto de este piso.
 dialog.querySelector('#undoPlan').onclick=()=>{const index=history.findLastIndex(h=>h.floor===floor),last=index<0?null:history.splice(index,1)[0],sheet=draft.floors[floor];if(!last){sheet?.strokes.pop();}else if(last.stroke)sheet.strokes.pop();else if(last.before)sheet.rooms[last.room]=last.before;else delete sheet.rooms[last.room];render();measure();};const close=()=>{serial++;clearTimeout(timer);dialog.remove();};dialog.oncancel=e=>{e.preventDefault();close();};dialog.querySelector('#cancelPlan').onclick=close;dialog.querySelector('#applyPlan').onclick=()=>{try{clearTimeout(timer);if(rooms.length&&draft.floors[floor])draft.floors[floor].avance=avanceGuardado(resumirAvance(medirAvance(rooms,draft.floors[floor],height/width)));validatePlan(draft);onSave(draft);close();}catch(error){status.textContent=error.message;}};await load();
}
